import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Gemini 一句话精确控制机位与运镜","description":"","frontmatter":{},"headers":[],"relativePath":"tools/gemini-camera-movement.md","filePath":"tools/gemini-camera-movement.md","lastUpdated":1787456457000}'),l={name:"tools/gemini-camera-movement.md"};function d(s,e,n,r,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="gemini-一句话精确控制机位与运镜" tabindex="-1">Gemini 一句话精确控制机位与运镜 <a class="header-anchor" href="#gemini-一句话精确控制机位与运镜" aria-label="Permalink to &quot;Gemini 一句话精确控制机位与运镜&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">来源</p><ul><li>来源：Gemini Web（Google Gemini）现场问答</li><li>时间：2026-08-15</li><li>说明：本文为用户向 Gemini Web 提问拿到的回答，仅做排版整理，文字未做改写。内容由 Gemini 生成，未经 Google 官方文档逐一核实；涉及 Veo 对具体运镜术语的支持程度请以官方文档为准。</li></ul></div><blockquote><p>提问：怎么用一句话精确指定机位和运镜？俯拍、环形运镜、dolly-in 在 Veo 里最稳的写法分别是什么？</p></blockquote><h2 id="核心句式结构" tabindex="-1">核心句式结构 <a class="header-anchor" href="#核心句式结构" aria-label="Permalink to &quot;核心句式结构&quot;">​</a></h2><p>在 Veo 中，单句提示词要达到工业级控制精度，核心句式结构是：</p><p><strong>[镜头起始景别与机位] + [精确运镜动词与轨迹] + [运动速度 / 节奏] + [锁定的视觉焦点与光影]</strong></p><p>避免使用文学化描述（如「慢慢地看过去」），直接使用标准摄影工业术语。以下是三种机位在 Veo 中最稳定、无歧义的写法与解析。</p><h2 id="_1-俯拍-top-down-overhead-shot" tabindex="-1">1. 俯拍（Top-down / Overhead Shot） <a class="header-anchor" href="#_1-俯拍-top-down-overhead-shot" aria-label="Permalink to &quot;1. 俯拍（Top-down / Overhead Shot）&quot;">​</a></h2><p>最稳单句写法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A static overhead bird&#39;s-eye view, perfectly top-down 90-degree angle, focused on [Subject] centered on [Surface] with soft diffused top lighting.</span></span></code></pre></div><p>关键术语解析：</p><ul><li><strong><code>perfectly top-down 90-degree angle</code></strong>：强制锁定绝对垂直俯视，防止模型生成 45 度的斜俯视角。</li><li><strong><code>overhead bird&#39;s-eye view</code></strong>：双重加固垂直空间认知。</li><li><strong><code>static</code></strong>：若不需要移动，务必加上 <code>static</code>，防止 AI 自行添加晃动。</li></ul><h2 id="_2-环形运镜-360°-orbit-arc-shot" tabindex="-1">2. 环形运镜（360° Orbit / Arc Shot） <a class="header-anchor" href="#_2-环形运镜-360°-orbit-arc-shot" aria-label="Permalink to &quot;2. 环形运镜（360° Orbit / Arc Shot）&quot;">​</a></h2><p>最稳单句写法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A smooth 180-degree orbital arc shot, circling around [Subject] from left to right at eye level, camera tracking tightly with seamless cinematic parallax.</span></span></code></pre></div><p>关键术语解析：</p><ul><li><strong><code>180-degree orbital arc shot</code>（或 <code>360-degree</code>）</strong>：明确弧形旋转的角度范围与起始方向（<code>from left to right</code>）。</li><li><strong><code>at eye level</code></strong>：锁死相机高度，防止镜头在环绕过程中上下起伏漂移。</li><li><strong><code>seamless cinematic parallax</code></strong>：诱导模型生成准确的前后景视差，强化 3D 纵深感。</li></ul><h2 id="_3-平滑推进-dolly-in-push-in" tabindex="-1">3. 平滑推进（Dolly-in / Push-in） <a class="header-anchor" href="#_3-平滑推进-dolly-in-push-in" aria-label="Permalink to &quot;3. 平滑推进（Dolly-in / Push-in）&quot;">​</a></h2><p>最稳单句写法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A controlled slow dolly-in shot, camera smoothly pushing forward along the z-axis from medium close-up into a crisp macro detail of [Subject], no lens distortion.</span></span></code></pre></div><p>关键术语解析：</p><ul><li><strong><code>along the z-axis</code></strong>：在空间几何层面上明确沿 Z 轴直线推进，杜绝左右晃动。</li><li><strong><code>from [A] into [B]</code></strong>：清晰定义起始景别（Medium close-up）与落点景别（Macro detail）。</li><li><strong><code>no lens distortion</code></strong>：避免广角镜头在极近距离推入时产生鱼眼畸变。</li></ul><h2 id="快速速查表" tabindex="-1">快速速查表 <a class="header-anchor" href="#快速速查表" aria-label="Permalink to &quot;快速速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机位 / 运镜</th><th>核心组合词</th><th>作用与避坑要点</th></tr></thead><tbody><tr><td>纯正俯拍</td><td><code>top-down 90-degree angle</code>, <code>overhead bird&#39;s-eye view</code></td><td>杜绝 45° 俯角倾斜</td></tr><tr><td>水平环绕</td><td><code>orbital arc shot</code>, <code>circling at eye level</code>, <code>cinematic parallax</code></td><td>锁定高度，防止环形运动中翻滚变形</td></tr><tr><td>直线推进</td><td><code>slow dolly-in along the z-axis</code>, <code>pushing from [A] to [B]</code></td><td>锁定运动轴线，精确控制景别过渡</td></tr></tbody></table><hr><p>关联：运镜的速度与节奏（slow motion、dolly-in、orbital）会直接决定单镜时长分配，配合 <a href="/tools/gemini-video-duration">控制视频时长</a> 第一行锁总长的方法一起用。</p>',26)])])}const m=t(l,[["render",d]]);export{g as __pageData,m as default};
